<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>MapleSure SponsorConnect</title>
    <style>
        body { font-family: Arial, sans-serif; margin: 20px; }
        #claim-form, #confirmation { max-width: 600px; margin: auto; }
        .hidden { display: none; }
        footer { margin-top: 20px; text-align: center; font-size: 0.8em; color: gray; }
        ul { list-style-type: none; padding: 0; }
    </style>
</head>
<body>
    <div id="analytics-script">
        <script>
            function trackEvent(type, detail) {
                console.log('Analytics Event:', { type, detail });
            }

            document.addEventListener('DOMContentLoaded', () => {
                trackEvent('view', { page: 'landing' });

                document.querySelector('#claim-form').addEventListener('submit', () => {
                    trackEvent('submit', { event: 'claim-form-submitted' });
                });

                document.querySelector('#claim-form button').addEventListener('click', () => {
                    trackEvent('click', { event: 'lookup-member-click', memberId: 'hidden' });
                });

                document.querySelectorAll('input, select').forEach(input => {
                    input.addEventListener('change', () => {
                        trackEvent('interaction', { field: input.id });
                    });
                });
            });
        </script>
    </div>

    <form id="claim-form">
        <h1>MapleSure SponsorConnect</h1>
        <section>
            <label for="policy-number">Policy Number:</label><br>
            <input type="text" id="policy-number"><br>

            <label for="member-id">Member ID:</label><br>
            <input type="text" id="member-id">
            <button type="button" onclick="lookupMember()">Look up member</button>

            <div id="member-details">
                <!-- Filled dynamically -->
            </div>
        </section>

        <section>
            <label for="last-day">Last Day Worked:</label><br>
            <input type="date" id="last-day"><br>

            <label for="first-day-absent">First Day Absent:</label><br>
            <input type="date" id="first-day-absent"><br>

            <label for="nature-of-absence">Nature of Absence:</label><br>
            <select id="nature-of-absence">
                <option value="">Select...</option>
                <option value="illness">Illness</option>
                <option value="injury">Injury</option>
                <option value="personal">Personal Reasons</option>
            </select><br>

            <label for="details">Details:</label><br>
            <textarea id="details" rows="4" cols="50"></textarea><br>

            <label for="documents">Upload Documents:</label><br>
            <input type="file" id="documents" multiple><br>
            <ul id="file-list"></ul>
        </section>

        <button type="submit">Submit Claim</button>
    </form>

    <div id="confirmation" class="hidden">
        <h2>Claim Submitted</h2>
        <p>Your claim reference number is: <span id="reference-number"></span></p>
        <p>Status: Received</p>
    </div>

    <footer>MapleSure Insurance fictional demo application</footer>

    <script>
        const mockData = {
            "12345": { name: "John Doe", claims: [] },
            "67890": { name: "Jane Smith", claims: [] }
        };

        function lookupMember() {
            const memberId = document.getElementById('member-id').value;
            const memberDetails = document.getElementById('member-details');
            if (mockData[memberId]) {
                memberDetails.innerHTML = `<p>Member: ${mockData[memberId].name}</p>`;
            } else {
                memberDetails.innerHTML = '<p>Member not found.</p>';
            }
            trackEvent('click', { event: 'lookup-member-click', memberId: 'hidden' });
        }

        document.getElementById('documents').addEventListener('change', function() {
            const fileList = document.getElementById('file-list');
            fileList.innerHTML = '';
            Array.from(this.files).forEach(file => {
                const li = document.createElement('li');
                li.textContent = file.name;
                fileList.appendChild(li);
            });
        });

        document.getElementById('claim-form').addEventListener('submit', function(event) {
            event.preventDefault();
            this.classList.add('hidden');
            document.getElementById('confirmation').classList.remove('hidden');
            document.getElementById('reference-number').textContent = generateReferenceNumber();
        });

        function generateReferenceNumber() {
            const suffix = String(Math.floor(1000 + Math.random() * 9000));
            return `MS-2026-08-${suffix}`;
        }
    </script>

</body>
</html>

